CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY, first_name TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'Europe/Chisinau', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS settings (user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, semester_start DATE, first_week_parity TEXT CHECK(first_week_parity IN ('even','odd')), english_duration INTEGER CHECK(english_duration BETWEEN 1 AND 240), sleep_hours NUMERIC NOT NULL DEFAULT 8, sleep_latency INTEGER NOT NULL DEFAULT 15, wash_minutes INTEGER NOT NULL DEFAULT 15, breakfast_minutes INTEGER NOT NULL DEFAULT 20, get_ready_minutes INTEGER NOT NULL DEFAULT 15, travel_buffer INTEGER NOT NULL DEFAULT 10, home_address TEXT, university_address TEXT, theme TEXT NOT NULL DEFAULT 'light', reminders_enabled BOOLEAN NOT NULL DEFAULT false, reminder_minutes INTEGER NOT NULL DEFAULT 60, wake_reminder BOOLEAN NOT NULL DEFAULT false, sleep_reminder BOOLEAN NOT NULL DEFAULT false, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE settings ADD COLUMN IF NOT EXISTS theme TEXT NOT NULL DEFAULT 'light';
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='settings_theme_check' AND conrelid='settings'::regclass) THEN ALTER TABLE settings ADD CONSTRAINT settings_theme_check CHECK(theme IN ('light','dark')); END IF; END $$;
ALTER TABLE settings ALTER COLUMN home_address SET DEFAULT 'strada Tudor Strișcă 8/7, Chișinău';
ALTER TABLE settings ALTER COLUMN university_address SET DEFAULT 'strada Alexei Mateevici 60, Chișinău';
UPDATE settings SET home_address='strada Tudor Strișcă 8/7, Chișinău' WHERE home_address IS NULL;
UPDATE settings SET university_address='strada Alexei Mateevici 60, Chișinău' WHERE university_address IS NULL;
CREATE TABLE IF NOT EXISTS homework (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, subject TEXT, due_at TIMESTAMPTZ, due_date DATE, note TEXT, completed BOOLEAN NOT NULL DEFAULT false, telegram_reminder BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS homework_user_due ON homework(user_id,due_at) WHERE completed=false;
CREATE TABLE IF NOT EXISTS notification_log (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, event_key TEXT NOT NULL, sent_at TIMESTAMPTZ, attempts INTEGER NOT NULL DEFAULT 0, next_attempt TIMESTAMPTZ, UNIQUE(user_id,event_key));
CREATE TABLE IF NOT EXISTS schedule_overrides (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, schedule JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS schedule_one_per_user ON schedule_overrides(user_id);
CREATE TABLE IF NOT EXISTS transit_state (id SMALLINT PRIMARY KEY CHECK(id=1), available BOOLEAN NOT NULL, source TEXT NOT NULL, checked_at TIMESTAMPTZ NOT NULL, note TEXT NOT NULL, estimate_minutes INTEGER NOT NULL, vehicle_count INTEGER);
